//! Synthetic opaque candidates only; authored/uncompiled/unrun.
use super::*;
fn selected()->(tempfile::TempDir,RestoreRequest,PathBuf,ProofRetentionRequest) {
    let (temporary,retention,source)=super::super::tests::fixture();let token=CancellationToken::new();let receipt=retain(&retention,&source,&token).unwrap();
    let request=RestoreRequest {schema:"aniflow.detached-proof-restore-request/v1".into(),source_directory:source,receipt_sha256:local::hash(&local::bytes(&receipt).unwrap()),maximum_total_bytes:16_777_216,minimum_free_bytes:0};
    let root=temporary.path().canonicalize().unwrap().join("restored");(temporary,request,root,retention)
}
#[test] fn restored_pair_is_self_contained_without_claiming_cryptographic_verification(){let (_temp,r,root,original)=selected();std::fs::remove_dir_all(&original.bundle_directory).unwrap();std::fs::remove_file(&original.proof_file).unwrap();let before=std::fs::read(r.source_directory.join("receipt.json")).unwrap();let result=restore(&r,&root,&CancellationToken::new()).unwrap();assert_eq!(result.timestamp_state,"not_verified");assert_eq!(result.subject_binding,BINDING);assert_eq!(std::fs::read(root.join("receipt.json")).unwrap(),before);assert_eq!(inspect(&root,&r.receipt_sha256,&CancellationToken::new()).unwrap(),inspect(&r.source_directory,&r.receipt_sha256,&CancellationToken::new()).unwrap());}
#[test] fn wrong_pin_or_changed_proof_refuses_without_destination_creation(){let (_temp,mut r,root,_)=selected();let pin=r.receipt_sha256.clone();r.receipt_sha256="0".repeat(64);assert!(restore(&r,&root,&CancellationToken::new()).is_err());assert!(!root.exists());r.receipt_sha256=pin;std::fs::write(r.source_directory.join("proof.ots"),b"changed").unwrap();assert!(restore(&r,&root,&CancellationToken::new()).is_err());assert!(!root.exists());}
#[test] fn total_budget_or_cancellation_refuses_before_creation(){let (_temp,mut r,root,_)=selected();r.maximum_total_bytes=1;assert!(restore(&r,&root,&CancellationToken::new()).is_err());assert!(!root.exists());r.maximum_total_bytes=16_777_216;let token=CancellationToken::new();token.cancel();assert!(restore(&r,&root,&token).is_err());assert!(!root.exists());}
#[test] fn existing_output_and_overlapping_source_are_preserved(){let (_temp,r,root,_)=selected();std::fs::create_dir(&root).unwrap();std::fs::write(root.join("keep"),b"preserve").unwrap();assert!(restore(&r,&root,&CancellationToken::new()).is_err());assert_eq!(std::fs::read(root.join("keep")).unwrap(),b"preserve");assert!(restore(&r,&r.source_directory.join("nested"),&CancellationToken::new()).is_err());}
#[test] fn symbolic_or_unknown_members_cannot_be_restored(){let (_temp,r,root,_)=selected();std::fs::write(r.source_directory.join("unknown"),b"preserve").unwrap();assert!(restore(&r,&root,&CancellationToken::new()).is_err());assert!(!root.exists());std::fs::remove_file(r.source_directory.join("unknown")).unwrap();#[cfg(unix)]{let path=r.source_directory.join("proof.ots");let outside=root.with_file_name("outside.ots");std::fs::rename(&path,&outside).unwrap();std::os::unix::fs::symlink(&outside,&path).unwrap();assert!(restore(&r,&root,&CancellationToken::new()).is_err());assert!(!root.exists());}}
#[test] fn successor_preserves_immediate_receipt_without_inventing_full_ancestry(){let (_temp,first,root,mut retention)=selected();retention.previous=Some(ProofPredecessor {directory:first.source_directory.clone(),receipt_sha256:first.receipt_sha256});std::fs::write(&retention.proof_file,b"second opaque candidate").unwrap();retention.expected_proof_sha256=local::hash(b"second opaque candidate");let second=root.with_file_name("successor");let receipt=retain(&retention,&second,&CancellationToken::new()).unwrap();let r=RestoreRequest {schema:"aniflow.detached-proof-restore-request/v1".into(),source_directory:second,receipt_sha256:local::hash(&local::bytes(&receipt).unwrap()),maximum_total_bytes:16_777_216,minimum_free_bytes:0};let result=restore(&r,&root,&CancellationToken::new()).unwrap();assert_eq!(result.copied_files,5);assert_eq!(inspect(&root,&r.receipt_sha256,&CancellationToken::new()).unwrap().sequence,2);assert_eq!(result.timestamp_state,"not_verified");}
